// Union 类型演示

function getLength(value) {
  // string | number → 需要区分处理
  if (typeof value === 'string') {
    return value.length  // string 有 .length
  }
  return String(value).length  // number 转 string 再取长度
}

console.log('abc 长度:', getLength('abc'))
console.log('12345 长度:', getLength(12345))
console.log('100 长度:', getLength(100))

var input = document.getElementById('narrowInput')
var result = document.getElementById('narrowResult')

function processValue(value) {
  // typeof 收窄：区分 string 和 number
  if (typeof value === 'number') {
    return '数值 → 平方 = ' + (value * value)
  }
  if (typeof value === 'string') {
    if (value.length === 0) return '空字符串'
    return '字符串 → 长度 = ' + value.length + '，大写 = ' + value.toUpperCase()
  }
  return '其他类型'
}

input.oninput = function() {
  var val = input.value
  // 尝试转数字
  if (!isNaN(Number(val)) && val !== '') {
    result.textContent = processValue(Number(val))
  } else {
    result.textContent = processValue(val)
  }
}

input.value = 'hello'
result.textContent = processValue('hello')

// 泛型的 JS 等价实现（JS 没有类型，所以不需要泛型）
// 但泛型的思想可以用 JS 日志来演示

function first(arr) {
  if (arr.length === 0) return undefined
  return arr[0]
}

console.log('first([1,2,3]) =', first([1, 2, 3]), '(类型:', typeof first([1, 2, 3]), ')')
console.log('first(["a","b"]) =', first(['a', 'b']), '(类型:', typeof first(['a', 'b']), ')')
console.log('first([{name:"x"}]) =', JSON.stringify(first([{ name: 'x' }])), '(对象)')

// 泛型约束等价于：要求参数有 .length 属性

function longer(a, b) {
  if (a.length === undefined || b.length === undefined) {
    return '❌ 参数必须有 .length 属性！'
  }
  return a.length > b.length ? a : b
}

var inpA = document.getElementById('genInputA')
var inpB = document.getElementById('genInputB')
var res = document.getElementById('genResult')

function update() {
  var a = inpA.value
  var b = inpB.value
  var r = longer(a, b)
  res.textContent = typeof r === 'string' ? r : ('较长的：' + r)
}

inpA.value = 'hello'
inpB.value = 'world!'
inpA.oninput = update
inpB.oninput = update
update()

// JS 中等价枚举的实现：对象模拟

var Status = {
  Pending: 0,
  Done: 1,
  Failed: 2
}

function getStatusText(status) {
  switch (status) {
    case Status.Pending: return '⏳ 待处理'
    case Status.Done: return '✅ 已完成'
    case Status.Failed: return '❌ 失败'
    default: return '未知'
  }
}

console.log('Status.Pending =', Status.Pending, '→', getStatusText(Status.Pending))
console.log('Status.Done =', Status.Done, '→', getStatusText(Status.Done))
console.log('Status.Failed =', Status.Failed, '→', getStatusText(Status.Failed))

