// TS 项目最终执行的还是 JS
// 演示一个完整的类型安全函数

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    return { ok: false, error: '参数必须是对象' }
  }
  if (!user.name || typeof user.name !== 'string') {
    return { ok: false, error: '缺少 name 字段' }
  }
  if (typeof user.age !== 'number' || user.age < 0) {
    return { ok: false, error: 'age 必须是非负数字' }
  }
  return { ok: true, data: user }
}

console.log('✅', validateUser({ name: '小明', age: 25 }))
console.log('❌', validateUser({ name: '小红' }))
console.log('❌', validateUser({ age: 18 }))

// TS 让这些检查从「运行时」提前到「编译时」
// 不用写一堆 if 校验，编译器帮你做！

// 最终演示：类型安全的工具函数集合

function safeGet(obj, key, defaultValue) {
  if (obj && typeof obj === 'object' && key in obj) {
    return obj[key]
  }
  return defaultValue
}

console.log('safeGet 演示:')
console.log(safeGet({ name: '小明' }, 'name', '未知'))
console.log(safeGet({ name: '小明' }, 'age', '未知'))

